export type UpcomingEventSeed = {
  slug: string;
  title: string;
  summary: string;
  description: string;
  category: ExperienceCategory;
  cuisine: string;
  tags: string[];
  dietary: string[];
  atmosphere: SocialAtmosphere;
  format: EventFormat;
  occasions: string[];
  highlights: string[];
  menu: { title: string; description: string }[];
  inclusions: string[];
  host: string;
  venue: string;
  priceDollars: number;
  durationMinutes: number;
  capacity: number;
  policy: "STANDARD_48H" | "FLEXIBLE_24H" | "STRICT_7D";
  /**
   * Cover from public/tastable-event-images when one fits (only caption-free images, or ones whose
   * baked-in caption matches the event); otherwise the placeholder photos lead.
   */
  cover?: string;
  photos: PhotoKey[];
  /** Start time in New York. */
  hour: number;
  minute: number;
  fill: "sold-out" | "nearly" | "busy" | "open";
  popularity: number;
  featured?: boolean;
};

const c = (title: string, description = "") => ({ title, description });
type Short = Omit<UpcomingEventSeed, "minute" | "policy" | "dietary" | "inclusions"> &
  Partial<Pick<UpcomingEventSeed, "minute" | "policy" | "dietary" | "inclusions">>;
const ev = (e: Short): UpcomingEventSeed => ({ minute: 0, policy: "STANDARD_48H", dietary: [], inclusions: ["Everything on the menu", "Hosted by the chef"], ...e });

