const pad = (n: number) => String(n).padStart(2, "0");
function addDays(iso: string, days: number) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

export const UPCOMING_WINDOW_DAYS = 14;

export type UpcomingPlacement = { event: UpcomingEventSeed; date: string; time: string; seatsReserved: number };

/**
 * Places the events on the next 14 days (today included). Each day aims for 3, 4 or 5 events in
 * total (alternating by date) and always gets at least one new event. `existing` counts the
 * other upcoming sessions per New York date; `nowNy` is the current New York date and time
 * ("YYYY-MM-DD HH:MM") so nothing is placed earlier today.
 */
export function planUpcoming(today: string, nowNy: string, existing: Record<string, number>): UpcomingPlacement[] {
  const pool = [...UPCOMING_EVENTS];
  const out: UpcomingPlacement[] = [];
  for (let d = 0; d < UPCOMING_WINDOW_DAYS && pool.length; d++) {
    const date = addDays(today, d);
    const target = 3 + (Number(date.slice(8)) % 3);
    let need = Math.max(1, target - (existing[date] ?? 0));
    const usedHosts = new Set<string>();
    for (let i = 0; i < pool.length && need > 0; ) {
      const e = pool[i];
      const time = `${pad(e.hour)}:${pad(e.minute)}`;
      // Today: only times at least an hour away. One event per host per day.
      const tooSoon = d === 0 && `${date} ${time}` <= addHour(nowNy);
      if (tooSoon || usedHosts.has(e.host)) {
        i++;
        continue;
      }
      pool.splice(i, 1);
      usedHosts.add(e.host);
      out.push({ event: e, date, time, seatsReserved: reservedFor(e) });
      need--;
    }
  }
  return out;
}

function addHour(nowNy: string) {
  const [date, time] = nowNy.split(" ");
  const h = Number(time.slice(0, 2)) + 1;
  return h >= 24 ? `${date} 23:59` : `${date} ${pad(h)}:${time.slice(3, 5)}`;
}

/** Simulated seats taken (no booking records are created for these events). */
export function reservedFor(e: UpcomingEventSeed) {
  switch (e.fill) {
    case "sold-out":
      return e.capacity;
    case "nearly":
      return e.capacity - 2;
    case "busy":
      return Math.round(e.capacity * 0.6);
    default:
      return Math.round(e.capacity * 0.3);
  }
}
